message.content:
{
"title": "Fee, Fly, Foe, Fund",
"language": "en",
"recommended_level": "6 – 8",
"hook": "Two tendays ago, cloud giants attacked the town of Nightstone, slaying many of its inhabitants including Lady Velrosa Nandar, a Waterdhavian noble and High Steward of the town.",
"npcs": [
    {
        "name": "Regina",
        "role": "Female halfling, assistant to Lord Talurth Nandar"
    },
    {
        "name": "Lord Talurth Nandar",
        "role": "Patriarch of House Nandar, looking for adventurers to investigate the attack on Nightstone"
    }
],
"locations": [
    "House Nandar's villa in the North Ward, Waterdeep",
    "Nandar hunting lodge in the Ardeep Forest"
],
"threats": [
    "Attacks by cloud giants",
    "Encounters with giant threats"
],
"rewards": [
    "100 gp for delivering the House Nandar crest",
    "250 gp per giant slain with proof in the form of severed right ears",
    "Additional 20% compensation for successful Persuasion checks",
    "Trust and future employment from the Lords’ Alliance"
]
}

